# Kurs Wahrscheinlichkeit & Statistik · Modul 5 (Stufe 2) und Modul 6 (Stufe 3)
from common import L, mc, num, multi, order, card, S_SEE, S_OS, S_KHAN, S_HENZE, S_HARD, S_GIG

M5 = {"id": "wkeit.m5", "level": 2, "title": "Zufallsgrößen, Erwartungswert, Streuung", "desc": "Was man im Mittel erwarten kann und wie stark es schwankt.", "lessons": [
 L("wkeit.m5.l1", "Zufallsgröße und Verteilung", 5, [
  "Eine Zufallsgröße X ordnet jedem Ergebnis eine Zahl zu, etwa die Augenzahl eines Würfels oder den Gewinn in Euro. Die Wahrscheinlichkeitsverteilung sagt, mit welcher Wahrscheinlichkeit X welchen Wert annimmt.",
  "## Beispiel: Summe zweier Würfel",
  "Die Summe kann 2 bis 12 sein, aber nicht gleich wahrscheinlich. Für die 7 gibt es 6 Kombinationen (1+6, 2+5, …, 6+1) von 36, also 1/6. Für die 2 oder die 12 gibt es nur je eine. Die Verteilung hat die Form eines Dachs. Probiere die Simulation unten aus.",
  "## Darstellung",
  "Verteilungen stellt man als Tabelle oder Säulendiagramm dar. Die Summe aller Wahrscheinlichkeiten ist immer 1."],
  ["Zufallsgröße: Ergebnis → Zahl.", "Verteilung: welcher Wert mit welcher Wahrscheinlichkeit.", "Summe zweier Würfel: 7 ist am häufigsten (1/6)."],
  [S_SEE, S_HENZE],
  [card("Zufallsgröße", "Funktion, die jedem Ergebnis eines Zufallsexperiments eine Zahl zuordnet."),
   card("Wahrscheinlichkeitsverteilung", "Angabe, mit welcher Wahrscheinlichkeit eine Zufallsgröße welche Werte annimmt.")],
  [num("Wie viele der 36 Kombinationen zweier Würfel ergeben die Summe 8?", 5, "", 0, "2+6, 3+5, 4+4, 5+3, 6+2."),
   mc("Welche Augensumme ist bei zwei Würfeln am wahrscheinlichsten?", ["7", "6", "12", "Alle gleich"], 0, "Die 7 hat mit 6 von 36 die meisten Kombinationen."),
   num("Wahrscheinlichkeit für die Summe 2 bei zwei Würfeln (in Prozent, gerundet)?", 2.8, "%", 0.2, "1/36 ≈ 2,8 %.")],
  figs=[{"after": 2, "w": "dice", "cap": "Würfle virtuell mit zwei Würfeln und vergleiche mit der Theorie."}]),
 L("wkeit.m5.l2", "Der Erwartungswert", 6, [
  "Der Erwartungswert E(X) ist der Mittelwert, den man bei sehr vielen Wiederholungen erwarten kann. Man rechnet: jeden Wert mal seine Wahrscheinlichkeit, alles addiert.",
  "## Beispiel Würfel",
  "E = 1·1/6 + 2·1/6 + … + 6·1/6 = 21/6 = 3,5. Kein einzelner Wurf zeigt 3,5, aber der Durchschnitt vieler Würfe liegt nahe 3,5.",
  "## Faires Spiel und Glücksspiel",
  "Ein Spiel ist fair, wenn der Erwartungswert des Gewinns 0 ist. Beim europäischen Roulette gewinnt ein Euro auf Rot mit 18/37 einen Euro und verliert mit 19/37 einen Euro: E = 18/37 − 19/37 = −1/37 ≈ −2,7 Cent pro Euro. Auf Dauer verliert man also im Schnitt 2,7 % des Einsatzes.",
  "## Lotto",
  "Beim Lotto fließt nur etwa die Hälfte der Einsätze als Gewinn zurück. Der Erwartungswert eines Tipps liegt deshalb weit unter dem Preis. Wer spielt, kauft Spannung, keine Rendite."],
  ["E(X) = Σ Wert · Wahrscheinlichkeit.", "Würfel: E = 3,5.", "Roulette: −2,7 % pro Einsatz; fair wäre E = 0."],
  [S_HENZE, S_OS, {"n": "LOTTO 6aus49: Ausschüttung von 50 % der Spieleinsätze laut Teilnahmebedingungen (Deutscher Lotto- und Totoblock)", "u": "https://www.lotto.de/"}],
  [card("Erwartungswert", "Langfristiger Mittelwert einer Zufallsgröße: Summe aus Wert mal Wahrscheinlichkeit."),
   card("Faires Spiel", "Spiel, bei dem der Erwartungswert des Gewinns 0 ist.")],
  [num("Ein Los kostet 2 €. Mit 10 % gewinnt man 10 €, sonst nichts. Wie hoch ist der erwartete Reingewinn pro Los in Euro?", -1, "€", 0.01, "0,1 · 10 € − 2 € = 1 € − 2 € = −1 €."),
   num("Erwartungswert der Augensumme zweier Würfel?", 7, "", 0, "3,5 + 3,5 = 7."),
   mc("Was bedeutet ein Erwartungswert von −0,05 € bei einem 1-€-Spiel?", ["Auf Dauer verliert man im Schnitt 5 Cent pro Spiel", "Jedes Spiel kostet genau 5 Cent", "Man gewinnt 5 % der Spiele", "Das Spiel ist fair"], 0, "Der Erwartungswert ist ein langfristiger Durchschnitt, kein fester Betrag pro Runde.")]),
 L("wkeit.m5.l3", "Varianz und Standardabweichung", 6, [
  "Zwei Spiele können den gleichen Erwartungswert haben und sich trotzdem völlig anders anfühlen: Eines zahlt immer 1 €, das andere mit 1 % 100 € und sonst nichts. Der Unterschied ist die Streuung.",
  "## Varianz",
  "Die Varianz misst die durchschnittliche quadrierte Abweichung vom Erwartungswert: Var(X) = Σ (Wert − E)² · Wahrscheinlichkeit. Beim Würfel ist sie 35/12 ≈ 2,92.",
  "## Standardabweichung",
  "Die Standardabweichung σ ist die Wurzel der Varianz und hat dieselbe Einheit wie die Daten. Beim Würfel ist σ ≈ 1,71. Faustregel: Die meisten Werte liegen innerhalb von ein bis zwei Standardabweichungen um den Mittelwert.",
  "## Wozu man das braucht",
  "In der Geldanlage gilt die Schwankung oft als Maß für das Risiko. In der Qualitätssicherung zeigt eine kleine Standardabweichung, dass ein Prozess gleichmäßig arbeitet."],
  ["Gleicher Erwartungswert, verschiedene Streuung möglich.", "Varianz: mittlere quadrierte Abweichung.", "Standardabweichung = √Varianz, gleiche Einheit wie die Daten."],
  [S_OS, S_HENZE],
  [card("Varianz", "Mittlere quadrierte Abweichung vom Erwartungswert."),
   card("Standardabweichung σ", "Wurzel aus der Varianz; typisches Maß der Streuung in der Einheit der Daten.")],
  [num("Ein Spiel zahlt mit 50 % 0 € und mit 50 % 2 €. Wie groß ist die Standardabweichung in Euro?", 1, "€", 0.01, "E = 1 €. Abweichungen ±1 €, quadriert 1, Varianz 1, Wurzel 1 €."),
   mc("Zwei Anlagen bringen im Mittel 5 % Rendite. A schwankt zwischen 4 und 6 %, B zwischen −20 und +30 %. Was gilt?", ["B hat die größere Standardabweichung", "Beide haben dasselbe Risiko", "A hat die größere Streuung", "B hat den höheren Erwartungswert"], 0, "Gleicher Mittelwert, aber B streut viel stärker."),
   mc("Warum quadriert man bei der Varianz die Abweichungen?", ["Damit sich positive und negative nicht aufheben", "Damit die Zahl kleiner wird", "Weil Quadrieren schneller ist", "Damit das Ergebnis Prozent ist"], 0, "Ohne Quadrieren wäre die Summe der Abweichungen vom Mittelwert immer 0.")]),
 L("wkeit.m5.l4", "Entscheiden mit Erwartungswert", 5, [
  "Der Erwartungswert hilft bei Entscheidungen unter Unsicherheit, aber er ist nicht alles.",
  "## Versicherungen",
  "Eine Haftpflichtversicherung hat aus Kundensicht einen negativen Erwartungswert, denn der Versicherer will Kosten decken und verdienen. Trotzdem ist sie sinnvoll: Sie schützt vor seltenen, aber ruinösen Schäden. Bei kleinen, verkraftbaren Schäden (Handyversicherung) lohnt es sich meist eher, das Risiko selbst zu tragen.",
  "## Risiko und Nutzen",
  "Menschen bewerten Verluste stärker als gleich große Gewinne. Deshalb zieht man oft 50 € sicher einer 50:50-Chance auf 100 € vor, obwohl der Erwartungswert gleich ist. Das ist nicht unbedingt falsch: Es kommt darauf an, was man sich leisten kann.",
  "## Faustregel",
  "Bei häufigen, kleinen Entscheidungen den Erwartungswert maximieren. Bei seltenen, existenzbedrohenden Risiken absichern, auch wenn es im Schnitt etwas kostet."],
  ["Erwartungswert = langfristiger Durchschnitt.", "Ruinöse Risiken absichern, kleine selbst tragen.", "Verlustaversion: Verluste wiegen schwerer als Gewinne."],
  [S_GIG, {"n": "Verbraucherzentrale: Ratgeber zu Versicherungen", "u": "https://www.verbraucherzentrale.de/"}],
  [card("Verlustaversion", "Verluste werden stärker gewichtet als gleich große Gewinne."),
   card("Versicherungsprinzip", "Seltene, große Schäden auf viele verteilen; im Schnitt kostet es etwas, schützt aber vor dem Ruin.")],
  [mc("Wann ist eine Versicherung trotz negativen Erwartungswerts sinnvoll?", ["Wenn der mögliche Schaden existenzbedrohend ist", "Wenn der Schaden sehr klein ist", "Wenn man nie Pech hat", "Wenn sie besonders günstig wirkt"], 0, "Gegen ruinöse Schäden lohnt sich die Absicherung, auch wenn sie im Schnitt kostet."),
   mc("Option A: 100 € sicher. Option B: 50 % auf 250 €, sonst 0 €. Welche hat den höheren Erwartungswert?", ["B mit 125 €", "A mit 100 €", "Beide gleich", "Das lässt sich nicht sagen"], 0, "0,5 · 250 € = 125 € > 100 €. Ob man B wählt, hängt aber auch vom Risiko ab.")])
]}

M6 = {"id": "wkeit.m6", "level": 3, "title": "Wichtige Verteilungen", "desc": "Binomial, Normal, Poisson und der zentrale Grenzwertsatz.", "lessons": [
 L("wkeit.m6.l1", "Die Binomialverteilung", 7, [
  "Wiederholt man ein Experiment n-mal unabhängig, und jedes Mal gibt es nur Treffer (Wahrscheinlichkeit p) oder Niete, dann zählt X die Treffer. X ist binomialverteilt.",
  "## Die Formel",
  "P(X = k) = (n über k) · pᵏ · (1 − p)ⁿ⁻ᵏ. „n über k“ zählt, an welchen Stellen die k Treffer liegen; pᵏ · (1 − p)ⁿ⁻ᵏ ist die Wahrscheinlichkeit eines solchen Pfads.",
  "## Beispiel",
  "Genau 5-mal Kopf bei 10 Münzwürfen: (10 über 5) · 0,5¹⁰ = 252/1024 ≈ 24,6 %. Selbst das wahrscheinlichste Ergebnis tritt also nur in jedem vierten Durchgang auf.",
  "## Kennzahlen",
  "Erwartungswert n · p, Standardabweichung √(n · p · (1 − p)). Bei 100 Münzwürfen: im Mittel 50 Kopf, Standardabweichung 5.",
  "## Galtonbrett",
  "Eine Kugel fällt durch Reihen von Nägeln und springt jedes Mal zufällig nach links oder rechts. Die Zahl der Rechtssprünge ist binomialverteilt. Unten siehst du, wie die Kugeln die typische Glockenform aufbauen."],
  ["Binomial: n unabhängige Versuche, Trefferwahrscheinlichkeit p.", "P(X = k) = (n über k) · pᵏ · (1 − p)ⁿ⁻ᵏ.", "E = n·p, σ = √(n·p·(1−p))."],
  [S_SEE, S_HENZE, S_OS],
  [card("Binomialverteilung", "Anzahl der Treffer bei n unabhängigen Versuchen mit gleicher Trefferwahrscheinlichkeit p."),
   card("Bernoulli-Experiment", "Ein Versuch mit genau zwei Ausgängen: Treffer oder Niete."),
   card("Galtonbrett", "Kugeln fallen durch Nagelreihen; die Verteilung in den Fächern ist binomial und ähnelt einer Glocke.")],
  [num("Wie groß ist P(genau 2 Sechsen bei 3 Würfen) in Prozent (gerundet)?", 6.9, "%", 0.2, "3 · (1/6)² · (5/6) = 15/216 ≈ 6,9 %."),
   num("Erwartete Anzahl Sechsen bei 60 Würfen?", 10, "", 0, "n·p = 60 · 1/6 = 10."),
   mc("Welche Voraussetzung gehört NICHT zur Binomialverteilung?", ["Die Trefferwahrscheinlichkeit steigt mit jedem Versuch", "Die Versuche sind unabhängig", "Es gibt nur Treffer oder Niete", "Die Anzahl der Versuche steht fest"], 0, "p muss bei jedem Versuch gleich bleiben.")],
  figs=[{"after": 7, "w": "galton", "cap": "Galtonbrett: Lass Kugeln fallen und beobachte, wie die Verteilung entsteht."}]),
 L("wkeit.m6.l2", "Die Normalverteilung", 6, [
  "Viele Größen in Natur und Technik verteilen sich glockenförmig um einen Mittelwert: Körpergröße, Messfehler, Füllmengen. Das Modell dafür ist die Normalverteilung mit Mittelwert μ und Standardabweichung σ.",
  "## Die 68-95-99,7-Regel",
  "Etwa 68 % der Werte liegen innerhalb von μ ± 1σ, etwa 95 % innerhalb von μ ± 2σ und etwa 99,7 % innerhalb von μ ± 3σ. Beispiel: Füllmenge 500 ml, σ = 4 ml. Dann liegen rund 95 % der Flaschen zwischen 492 und 508 ml.",
  "## Standardisieren",
  "Mit z = (x − μ) ÷ σ rechnet man jeden Wert in „Standardabweichungen vom Mittelwert“ um. Ein z-Wert von 2 heißt: zwei Standardabweichungen über dem Durchschnitt, das erreichen nur etwa 2,3 %.",
  "## Vorsicht",
  "Nicht alles ist normalverteilt. Einkommen, Vermögen, Schadenshöhen oder Börsencrashs haben „dicke Ränder“: Extreme sind viel häufiger, als die Normalverteilung vorhersagt."],
  ["68-95-99,7: Anteile innerhalb 1, 2, 3 σ.", "z = (x − μ) ÷ σ.", "Nicht alles ist normalverteilt, Extreme oft häufiger."],
  [S_OS, S_SEE],
  [card("Normalverteilung", "Glockenförmige Verteilung, festgelegt durch Mittelwert μ und Standardabweichung σ."),
   card("68-95-99,7-Regel", "Anteil der Werte innerhalb μ ± 1σ, 2σ, 3σ bei der Normalverteilung."),
   card("z-Wert", "(x − μ) ÷ σ: Abstand vom Mittelwert in Standardabweichungen.")],
  [num("IQ-Tests sind auf μ = 100 und σ = 15 genormt. Wie viel Prozent liegen ungefähr zwischen 85 und 115?", 68, "%", 1, "Das ist μ ± 1σ, also etwa 68 %."),
   num("Welcher z-Wert gehört zu x = 130 bei μ = 100, σ = 15?", 2, "", 0, "(130 − 100) ÷ 15 = 2."),
   mc("Welche Größe ist am wenigsten normalverteilt?", ["Vermögen der Haushalte", "Körpergröße erwachsener Frauen", "Messfehler einer Waage", "Füllmenge einer Abfüllanlage"], 0, "Vermögen ist stark schief verteilt: wenige sehr hohe Werte.")],
  figs=[{"after": 3, "w": "normal", "cap": "Normalverteilung: Wähle den Bereich μ ± kσ und sieh den Anteil."}]),
 L("wkeit.m6.l3", "Seltene Ereignisse: Poisson", 5, [
  "Wie viele Anrufe kommen pro Minute, wie viele Fehler pro Seite, wie viele Unfälle pro Monat an einer Kreuzung? Wenn Ereignisse unabhängig und mit konstanter mittlerer Rate λ auftreten, ist ihre Anzahl Poisson-verteilt.",
  "## Formel",
  "P(X = k) = λᵏ · e^(−λ) ÷ k!. Erwartungswert und Varianz sind beide λ.",
  "## Beispiel",
  "Eine Hotline bekommt im Schnitt 2 Anrufe pro Minute. Die Wahrscheinlichkeit für eine Minute ganz ohne Anruf ist e^(−2) ≈ 13,5 %. Für genau 2 Anrufe: 2² · e^(−2) ÷ 2 ≈ 27,1 %.",
  "## Häufung ist normal",
  "Auch rein zufällig auftretende Ereignisse kommen in Klumpen. Drei Unfälle in einer Woche an einer sonst ruhigen Kreuzung können Zufall sein; erst ein Vergleich mit der Poisson-Erwartung zeigt, ob etwas auffällig ist."],
  ["Poisson: Anzahl seltener, unabhängiger Ereignisse bei Rate λ.", "E = Var = λ.", "Zufällige Ereignisse häufen sich manchmal ganz natürlich."],
  [S_OS, S_HENZE],
  [card("Poisson-Verteilung", "Anzahl von Ereignissen in einem Zeitraum bei konstanter mittlerer Rate λ; E = Var = λ.")],
  [num("Mittlere Rate 1 Ereignis pro Stunde. Wahrscheinlichkeit für keine Ereignisse in einer Stunde (in Prozent, gerundet)?", 36.8, "%", 0.3, "e^(−1) ≈ 0,368."),
   mc("Was gilt bei der Poisson-Verteilung für Erwartungswert und Varianz?", ["Beide sind gleich λ", "Die Varianz ist λ²", "Der Erwartungswert ist 1", "Beide sind 0"], 0, "Das ist eine Besonderheit der Poisson-Verteilung.")]),
 L("wkeit.m6.l4", "Der zentrale Grenzwertsatz", 6, [
  "Warum taucht die Glockenkurve so oft auf? Der zentrale Grenzwertsatz liefert den Grund: Addiert oder mittelt man viele unabhängige Zufallsgrößen, ist das Ergebnis annähernd normalverteilt, egal wie die einzelnen Größen verteilt sind (solange ihre Varianz endlich ist).",
  "## Anschaulich",
  "Ein Würfel ist gleichverteilt, keine Glocke. Die Summe von zwei Würfeln ist schon ein Dach. Die Summe von zehn Würfeln sieht bereits aus wie eine Glocke. Das Galtonbrett zeigt dasselbe: jede Kugel macht viele kleine, zufällige Schritte.",
  "## Folgen für Mittelwerte",
  "Der Mittelwert aus n Messungen streut um den wahren Wert mit Standardabweichung σ ÷ √n. Viermal so viele Messungen halbieren also die Unsicherheit. Darauf beruhen Umfragen, Qualitätskontrollen und Konfidenzintervalle."],
  ["Summen und Mittelwerte vieler unabhängiger Größen → annähernd normal.", "Streuung des Mittelwerts: σ ÷ √n.", "Vierfache Stichprobe → halbe Unsicherheit."],
  [S_SEE, S_OS],
  [card("Zentraler Grenzwertsatz", "Summen und Mittelwerte vieler unabhängiger Zufallsgrößen sind annähernd normalverteilt."),
   card("Standardfehler", "Streuung eines Mittelwerts: σ ÷ √n.")],
  [mc("Wie verändert sich die Unsicherheit eines Mittelwerts, wenn man statt 100 nun 400 Messungen macht?", ["Sie halbiert sich", "Sie viertelt sich", "Sie bleibt gleich", "Sie verdoppelt sich"], 0, "σ ÷ √n: √400 = 20 statt √100 = 10, also halb so groß."),
   mc("Was besagt der zentrale Grenzwertsatz im Kern?", ["Mittelwerte vieler Zufallsgrößen sind annähernd normal", "Alle Daten sind normalverteilt", "Große Stichproben haben keine Streuung", "Zufall verschwindet bei vielen Daten"], 0, "Er gilt für Summen und Mittelwerte, nicht für die einzelnen Daten.")])
]}
